from collections import Counter


def transform(grid):
    """Pack the non-background motif against a full 2-divider and mark its far edge."""
    g = [row[:] for row in grid]
    h = len(g)
    if not h or not g[0]:
        return g
    w = len(g[0])
    if any(len(row) != w for row in g):
        return g

    divider = 2
    # A complete row/column of 2 defines the packing direction.
    dividers = [("row", r) for r in range(h) if all(g[r][c] == divider for c in range(w))]
    dividers += [("col", c) for c in range(w) if all(g[r][c] == divider for r in range(h))]
    if not dividers:
        return g
    axis, d = dividers[0]

    counts = Counter(v for row in g for v in row if v != divider)
    if not counts:
        return g
    background = counts.most_common(1)[0][0]
    motif_colors = [v for v in counts if v != background]
    if len(motif_colors) != 1:
        return g
    motif = motif_colors[0]
    points = [(r, c) for r in range(h) for c in range(w) if g[r][c] == motif]
    if not points:
        return g

    coords = [r if axis == "row" else c for r, c in points]
    lo, hi = min(coords), max(coords)
    if hi < d:
        delta = (d - 1) - hi
        new_lo, new_hi = lo + delta, hi + delta
        marker = new_lo - 1
    elif lo > d:
        delta = (d + 1) - lo
        new_lo, new_hi = lo + delta, hi + delta
        marker = new_hi + 1
    else:
        # A motif crossing the divider is not a packable object.
        return g

    if marker < 0 or marker >= (h if axis == "row" else w):
        return g

    out = [row[:] for row in g]
    for r, c in points:
        out[r][c] = background
    for r, c in points:
        if axis == "row":
            r += delta
        else:
            c += delta
        out[r][c] = motif

    if axis == "row":
        for c in range(w):
            out[marker][c] = 8
    else:
        for r in range(h):
            out[r][marker] = 8
    return out


